body:
Two callers can both pass the source/destination checks and enter this copy without any cross-instance claim. On this head, concurrent renames of one source to `left` and `right` produced one success and one source-removal error, but a fresh observer found both destinations: `(successes, destinations) = (1, 2)`. A failed call has therefore published durable namespace state. An independent run also had two different sources both return success while renaming into the same destination, retiring both sources behind one name. Reserve both names atomically and copy only into caller-owned staging, or keep no-manifest rename unsupported.

<details><summary>Reproducer</summary>

Added alongside the existing test module and ran `CARGO_TARGET_DIR=/home/agent/tmp/gate-pr6975-target-local-3078-r3 cargo test -p lance-namespace-impls gate_repro_v1_concurrent_renames_publish_two_destinations -- --nocapture`:

```rust
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn gate_repro_v1_concurrent_renames_publish_two_destinations() {
    let temp_dir = TempStdDir::default();
    let root = temp_dir.to_str().unwrap();
    let setup = DirectoryNamespaceBuilder::new(root)
        .manifest_enabled(false)
        .build().await.unwrap();
    let mut create = CreateTableRequest::new();
    create.id = Some(vec!["source".to_string()]);
    setup.create_table(
        create,
        Bytes::from(create_non_empty_test_ipc_data()),
    ).await.unwrap();

    let left = DirectoryNamespaceBuilder::new(root)
        .manifest_enabled(false).build().await.unwrap();
    let right = DirectoryNamespaceBuilder::new(root)
        .manifest_enabled(false).build().await.unwrap();
    let barrier = Arc::new(tokio::sync::Barrier::new(2));
    let left_barrier = barrier.clone();

    let left_rename = async {
        let mut request = RenameTableRequest::new("left".to_string());
        request.id = Some(vec!["source".to_string()]);
        left_barrier.wait().await;
        left.rename_table(request).await
    };
    let right_rename = async {
        let mut request = RenameTableRequest::new("right".to_string());
        request.id = Some(vec!["source".to_string()]);
        barrier.wait().await;
        right.rename_table(request).await
    };
    let (a, b) = tokio::join!(left_rename, right_rename);
    let successes = usize::from(a.is_ok()) + usize::from(b.is_ok());

    let observer = DirectoryNamespaceBuilder::new(root)
        .manifest_enabled(false).build().await.unwrap();
    let mut destinations = 0;
    for name in ["left", "right"] {
        let mut request = TableExistsRequest::new();
        request.id = Some(vec![name.to_string()]);
        destinations += usize::from(observer.table_exists(request).await.is_ok());
    }

    assert_eq!((successes, destinations), (1, 1));
}
